using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiModel = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

// --- Build the chat client with automatic function invocation ---
IChatClient client = new ChatClientBuilder(
        new OpenAIClient(openAiKey).GetChatClient(openAiModel).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// --- Instantiate the tools ---
var researchTools = new ResearchTools();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(researchTools.SaveNote),
    AIFunctionFactory.Create(researchTools.GetNotes),
};

// --- Get the research topic ---
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

// --- Run the agent loop ---
List<ChatMessage> messages =
[
    new(ChatRole.System, """
        You are a research assistant. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries).
        2. Saving important findings as notes.
        3. After gathering enough information, reviewing your notes and producing a
           well-structured summary with key findings and sources.

        Always search at least 2-3 different queries to get diverse perspectives.
        Save notable facts and findings as notes before writing the final summary.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"),
];

var options = new ChatOptions { Tools = tools };

var response = await client.GetResponseAsync(messages, options);

Console.WriteLine("\n📋 Research Complete!\n");
Console.WriteLine(response.Text);

// Show collected notes
var notes = researchTools.GetAllNotes();
if (notes.Count > 0)
{
    Console.WriteLine($"\n📝 Notes collected: {notes.Count}");
    foreach (var (title, content) in notes)
    {
        Console.WriteLine($"  • {title}");
    }
}

// === Tool Definitions ===

/// <summary>Tools available to the research agent.</summary>
class ResearchTools
{
    private static readonly HttpClient s_http = new();
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Search the web for information on a query. Returns a list of results with titles, URLs, and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API (no key required)
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

            s_http.DefaultRequestHeaders.UserAgent.Clear();
            s_http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

            var json = await s_http.GetFromJsonAsync<JsonElement>(url);

            var results = new List<string>();

            // Abstract (main answer)
            var abstractText = json.GetProperty("Abstract").GetString();
            var abstractSource = json.GetProperty("AbstractSource").GetString();
            var abstractUrl = json.GetProperty("AbstractURL").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add($"**{abstractSource}**: {abstractText}\nURL: {abstractUrl}");
            }

            // Related topics
            if (json.TryGetProperty("RelatedTopics", out var related))
            {
                foreach (var item in related.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) &&
                        item.TryGetProperty("FirstURL", out var itemUrl))
                    {
                        results.Add($"- {text.GetString()}\n  URL: {itemUrl.GetString()}");
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for \"{query}\". Try a different search query.";
            }

            Console.WriteLine($"    ✅ Found {results.Count} result(s)");
            return string.Join("\n\n", results);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note with a title and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The note content with facts and source references")] string content)
    {
        _notes.Add((title, content));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note \"{title}\" saved successfully. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes to review before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var formatted = _notes.Select((n, i) =>
            $"Note {i + 1}: {n.Title}\n{n.Content}");
        return string.Join("\n---\n", formatted);
    }

    public List<(string Title, string Content)> GetAllNotes() => _notes;
}

